"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[849],{6164(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/docs/","label":"Welcome to WLEDger","docId":"index","unlisted":false},{"type":"category","label":"Software","items":[{"type":"link","href":"/docs/Software/quickstart-guide","label":"Quick Start","docId":"Software/quickstart-guide","unlisted":false},{"type":"category","label":"Feature Guide","items":[{"type":"link","href":"/docs/Software/feature-guide/dashboard","label":"Dashboard","docId":"Software/feature-guide/dashboard","unlisted":false},{"type":"link","href":"/docs/Software/feature-guide/inventory","label":"Inventory","docId":"Software/feature-guide/inventory","unlisted":false},{"type":"link","href":"/docs/Software/feature-guide/inspiration","label":"Inspiration","docId":"Software/feature-guide/inspiration","unlisted":false},{"type":"link","href":"/docs/Software/feature-guide/hardware","label":"Hardware (WLED & Containers)","docId":"Software/feature-guide/hardware","unlisted":false},{"type":"link","href":"/docs/Software/feature-guide/audit-logs","label":"Audit Logs","docId":"Software/feature-guide/audit-logs","unlisted":false},{"type":"link","href":"/docs/Software/feature-guide/settings","label":"Settings","docId":"Software/feature-guide/settings","unlisted":false},{"type":"link","href":"/docs/Software/feature-guide/projects","label":"Projects & BOM Pick Mode","docId":"Software/feature-guide/projects","unlisted":false},{"type":"link","href":"/docs/Software/feature-guide/api","label":"REST API v1 & Personal Access Tokens","docId":"Software/feature-guide/api","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/Software/feature-guide/inventory"},{"type":"link","href":"/docs/Software/troubleshooting","label":"Troubleshooting","docId":"Software/troubleshooting","unlisted":false},{"type":"link","href":"/docs/Software/developer-guide","label":"Developer Guide","docId":"Software/developer-guide","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Hardware","items":[{"type":"link","href":"/docs/Hardware/build-guide","label":"Build Guide","docId":"Hardware/build-guide","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"Hardware/build-guide":{"id":"Hardware/build-guide","title":"Build Guide","description":"WLEDger\'s full power is realized when paired with a WLED controller, and some LEDs connected to your storage bins, shelves, etc.","sidebar":"tutorialSidebar"},"index":{"id":"index","title":"Welcome to WLEDger","description":"WLEDger is a high-performance inventory management system for electronics hobbyists, makers, and workshops. It bridges the gap between your digital inventory and physical storage by integrating with WLED controllers to physically light up the exact location of your parts \u2014 while also supporting controller-less standalone storage containers.","sidebar":"tutorialSidebar"},"Software/developer-guide":{"id":"Software/developer-guide","title":"Developer Guide","description":"Welcome to the WLEDger Developer Guide. This document details the Pure-Go architecture, project structure, and development workflow.","sidebar":"tutorialSidebar"},"Software/feature-guide/api":{"id":"Software/feature-guide/api","title":"REST API v1 & Personal Access Tokens","description":"WLEDger exposes a Bearer-authenticated JSON REST API under /api/v1/* for scripting, CI/CD inventory syncs, label printers, and Home Assistant / workshop automation.","sidebar":"tutorialSidebar"},"Software/feature-guide/audit-logs":{"id":"Software/feature-guide/audit-logs","title":"Audit Logs","description":"Audit Logs provide a record of all significant actions performed within WLEDger. This transparency is useful for accountability, troubleshooting, and maintaining the integrity of your inventory, especially in multi-user or shared environments.","sidebar":"tutorialSidebar"},"Software/feature-guide/dashboard":{"id":"Software/feature-guide/dashboard","title":"Dashboard","description":"The Dashboard gives you a real-time visual overview of your inventory, displaying WLED controller connectivity, unique part count, total stock count, total inventory value, and color-coded storage bin maps.","sidebar":"tutorialSidebar"},"Software/feature-guide/hardware":{"id":"Software/feature-guide/hardware","title":"Hardware (WLED & Containers)","description":"WLEDger\'s defining feature is bridging digital inventory and physical storage. Connect WLED controllers to illuminate exact bins on demand \u2014 or use controller-less Standalone Containers when organizing bins without LEDs.","sidebar":"tutorialSidebar"},"Software/feature-guide/inspiration":{"id":"Software/feature-guide/inspiration","title":"Inspiration","description":"WLEDger can help you decide what to build next by generating structured prompts for Large Language Models (LLMs) like Gemini, ChatGPT, or Claude based on your actual current inventory. This turns your component list into a powerful project brainstorming tool.","sidebar":"tutorialSidebar"},"Software/feature-guide/inventory":{"id":"Software/feature-guide/inventory","title":"Inventory","description":"WLEDger provides a high-performance inventory database powered by pure-Go SQLite FTS5. Organize your components, scan 2D supplier bags directly from your bench or phone, track physical locations across WLED and Standalone containers, and monitor stock levels.","sidebar":"tutorialSidebar"},"Software/feature-guide/projects":{"id":"Software/feature-guide/projects","title":"Projects & BOM Pick Mode","description":"WLEDger V2 brings Projects and BOM Kitting directly into your workshop workflow \u2014 letting you import KiCad or CSV Bills of Materials, check multi-board stock shortages, illuminate every needed bin at once in Pick Mode, and deduct inventory atomically when you build a board.","sidebar":"tutorialSidebar"},"Software/feature-guide/settings":{"id":"Software/feature-guide/settings","title":"Settings","description":"The Settings panel is the control center for your WLEDger instance. Manage users and roles, create scoped Personal Access Tokens for the REST API, configure guest read access, customize locate automation and colors, back up or restore your system, and update your password.","sidebar":"tutorialSidebar"},"Software/quickstart-guide":{"id":"Software/quickstart-guide","title":"Quick Start","description":"Get WLEDger V2 up and running in minutes via Docker or a standalone Pure-Go binary.","sidebar":"tutorialSidebar"},"Software/troubleshooting":{"id":"Software/troubleshooting","title":"Troubleshooting","description":"If you encounter unexpected behavior, enable Enable Debug Logs in Settings and inspect your container or process output. Then file an Issue on GitHub or reach out on the WLEDger Discord.","sidebar":"tutorialSidebar"}}}}')}}]);